using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using System.Reflection;using System.Drawing;using Frociart;
internal static class CycleTests {
 static int checks;static void Check(bool yes,string text){if(!yes)throw new Exception(text);checks++;}
 static string Enc(Diagram d){return Convert.ToBase64String(DiagramIO.EncodeDocument(d));}
 static string Run(Diagram d){var r=new Interpreter(d);for(int i=0;i<500&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Run completes: "+r.Error);return String.Join("|",r.Output);}
 static string Topology(Diagram d){return String.Join("|",d.Nodes.Select(n=>n.Id+":"+n.Kind))+String.Join("|",d.Edges.Select(e=>e.Id+":"+e.From+":"+e.To+":"+e.Branch));}
 static void Pump(){var t=System.Diagnostics.Stopwatch.StartNew();while(t.ElapsedMilliseconds<430){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static object Get(object o,string n){var f=BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance;return o.GetType().GetField(n,f).GetValue(o);}
 static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
 [STAThread]static int Main(string[] args){try{Directory.CreateDirectory(args[0]);
  for(int kind=0;kind<3;kind++){var baseD=DiagramIO.CreateBlank();var d=FlowLoopBuilder.Prepare(baseD,null,baseD.Edges[0].Id,FlowLoopBuilder.Spec.Default(kind)).Project;foreach(var n in d.Nodes){n.Comment="nota "+n.Kind;n.Breakpoint=true;n.BreakpointCondition="vero";if(n.Kind==NodeKind.Decision)n.TrueLabel="Dentro";}var info=FlowCycle.Find(d).Single();Check(info.Kind==kind,"Recognize kind "+kind);Check(!info.Members.Contains(d.Nodes.First(n=>n.Kind==NodeKind.Start).Id)&&!info.Members.Contains(d.Nodes.First(n=>n.Kind==NodeKind.End).Id),"Group excludes surrounding blocks");string before=Enc(d),topology=Topology(d);var spec=info.Spec;if(kind==0)spec.To="3";else spec.Condition="i < 3";var plan=FlowCycle.Prepare(d,null,info,spec);Check(Enc(d)==before,"Prepare immutable");Check(Topology(plan.Project)==topology,"Every node and edge ID retained");Check(Run(plan.Project)==(kind==0?"1|2|3":"0|1|2"),"Edited loop result "+kind);foreach(var old in d.Nodes){var n=plan.Project.Nodes.First(x=>x.Id==old.Id);Check(n.Comment==old.Comment&&n.Breakpoint==old.Breakpoint&&n.BreakpointCondition==old.BreakpointCondition&&n.TrueLabel==old.TrueLabel,"Presentation and debug metadata retained");if(!info.Members.Contains(n.Id)&&n.Kind!=NodeKind.End)Check(n.X==old.X&&n.Y==old.Y,"Upstream stays fixed");}Check(FlowCycle.Find(plan.Project).Single().Kind==kind,"Remains editable");DiagramIO.Save(Path.Combine(args[0],"pc-cycle-"+kind+".frociart"),plan.Project);Check(Run(DiagramIO.Load(Path.Combine(args[0],"pc-cycle-"+kind+".frociart")))==(kind==0?"1|2|3":"0|1|2"),"Save/reopen result");
   if(kind==0){var dyn=FlowCycle.Find(plan.Project).Single();dyn.Spec.Step="int(2)";var updated=FlowCycle.Prepare(plan.Project,null,dyn,dyn.Spec);Check(Run(updated.Project)=="1|3","Constant to dynamic step");var back=FlowCycle.Find(updated.Project).Single();back.Spec.Step="1";Check(Run(FlowCycle.Prepare(updated.Project,null,back,back.Spec).Project)=="1|2|3","Dynamic to constant step");var bad=FlowCycle.Find(d).Single();bad.Spec.Step="0";bool rejected=false;try{FlowCycle.Prepare(d,null,bad,bad.Spec);}catch(ArgumentException){rejected=true;}Check(rejected&&Enc(d)==before,"Invalid step leaves original intact");}
   using(var edit=new LoopEditorDialog(d,null,null,FlowCycle.Find(d).Single())){edit.Show();Pump();Check(edit.Kind.Enabled==false&&edit.Variable.ReadOnly&&!edit.Body.Visible,"Header editor preserves graph body");if(kind==0)edit.To.Text="2";else edit.Condition.Text="i < 2";edit.Save();Check(edit.Result!=null&&Run(edit.Result.Project)==(kind==0?"1|2":"0|1"),"Actual native editor saves "+kind);}
  }
  var nested=FlowPseudocode.Decode("INIZIO\nPER i DA 1 A 2 FAI\nPER j DA 1 A 2 FAI\nSTAMPA i * 10 + j\nFINE PER\nFINE PER\nFINE");var groups=FlowCycle.Find(nested);Check(groups.Count==2&&groups.All(i=>i.Kind==0),"Nested cycles distinct");var inner=groups.OrderBy(i=>i.Members.Count).First();inner.Spec.To="3";Check(Run(FlowCycle.Prepare(nested,null,inner,inner.Spec).Project)=="11|12|13|21|22|23","Edit only nested cycle");
  var unsafeGraph=DiagramIO.Clone(nested);var outer=FlowCycle.Find(unsafeGraph).OrderByDescending(i=>i.Members.Count).First();unsafeGraph.Edges.Add(new FlowEdge{From=unsafeGraph.Nodes.First(n=>n.Kind==NodeKind.Start).Id,To=outer.BodyEntry});Check(!FlowCycle.Find(unsafeGraph).Any(i=>i.Kind==0&&i.Entry==outer.Entry),"Multiple entrances rejected conservatively");
  var fn=FlowPseudocode.Decode("FUNZIONE f(n: INTERO) -> INTERO risultato\nrisultato=0\nPER i DA 1 A n FAI\nrisultato=risultato+i\nFINE PER\nFINE FUNZIONE\nINIZIO\nSTAMPA f(4)\nFINE");var f=fn.Functions[0];var fi=FlowCycle.Find(f.Body).Single();fi.Spec.To="2";var fp=FlowCycle.Prepare(fn,f.Id,fi,fi.Spec);Check(Run(fp.Project)=="3"&&Topology(fn)==Topology(fp.Project),"Function edit leaves main fixed");
  using(var main=new MainForm(null,true)){main.Show();Pump();main.SetDocument(nested,null,false);string before=Enc(main.Project);var info=FlowCycle.Find(nested).OrderBy(i=>i.Members.Count).First();info.Spec.To="3";main.ApplyLoopPlan(FlowCycle.Prepare(nested,null,info,info.Spec));Check(Run(main.Project)=="11|12|13|21|22|23","Native apply plan executes");Call(main,"Undo");Check(Enc(main.Project)==before,"One exact undo");Call(main,"Redo");Check(Run(main.Project)=="11|12|13|21|22|23","Exact redo");main.Canvas.SelectGroup(info.Members);Check(main.Canvas.SelectionCount==info.Members.Count,"Whole cycle selection");using(var b=new Bitmap(main.Width,main.Height)){main.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(args[0],"pc-cycle-selected.png"));}main.SetDocument(new Diagram(),null,false);main.Close();}
  var blankLong=DiagramIO.CreateBlank();var longD=FlowLoopBuilder.Prepare(blankLong,null,blankLong.Edges[0].Id,FlowLoopBuilder.Spec.Default(0)).Project;var longInfo=FlowCycle.Find(longD).Single();longInfo.Spec.To="1"+String.Concat(Enumerable.Repeat("+1",60));longInfo.Spec.Step="int(2)";var longPlan=FlowCycle.Prepare(longD,null,longInfo,longInfo.Spec);for(int i=0;i<longPlan.Project.Nodes.Count;i++)for(int j=i+1;j<longPlan.Project.Nodes.Count;j++)Check(!FlowCanvas.GetNodeBounds(longPlan.Project.Nodes[i]).IntersectsWith(FlowCanvas.GetNodeBounds(longPlan.Project.Nodes[j])),"Larger loop helpers do not overlap");Check(longD.Nodes[0].X==longPlan.Project.Nodes[0].X&&longD.Nodes[0].Y==longPlan.Project.Nodes[0].Y,"Long header leaves upstream anchor fixed");
  var nestedInfo=FlowCycle.Find(nested).OrderBy(i=>i.Members.Count).First();nestedInfo.Spec.To="1"+String.Concat(Enumerable.Repeat("+1",60));nestedInfo.Spec.Step="int(2)";var nestedLong=FlowCycle.Prepare(nested,null,nestedInfo,nestedInfo.Spec).Project;for(int i=0;i<nestedLong.Nodes.Count;i++)for(int j=i+1;j<nestedLong.Nodes.Count;j++)Check(!FlowCanvas.GetNodeBounds(nestedLong.Nodes[i]).IntersectsWith(FlowCanvas.GetNodeBounds(nestedLong.Nodes[j])),"Nested helper growth does not overlap enclosing continuation");
  using(var motionMain=new MainForm(null,true)){motionMain.Show();Pump();motionMain.SetDocument(longD,null,false);motionMain.Canvas.Invalidate();Pump();motionMain.ApplyLoopPlan(longPlan);var frames=(System.Collections.IDictionary)Get(motionMain.Canvas,"sizeMotion");bool hasGrowth=false;foreach(var frame in frames.Values)hasGrowth|=(SizeF)Get(frame,"From")!=(SizeF)Get(frame,"To");Check(!UiMotion.Enabled||hasGrowth,"Cycle size replacement starts with prior geometry for spring animation");motionMain.SetDocument(new Diagram(),null,false);motionMain.Close();}
  foreach(string s in new[]{"non (\"(\" == \"(\")","non (\"a)\" == \"a)\")","non (vero) e (falso)"})Check((bool)ExpressionLanguage.Evaluate(FlowCycle.Negate(s),null)==!(bool)ExpressionLanguage.Evaluate(s,null),"Negation preserves quoted parentheses");
  var nulls=DiagramIO.CreateBlank();nulls.Nodes.Add(new FlowNode{Kind=NodeKind.Process,Text=null});Check(FlowCycle.Find(nulls).Count==0,"Null legacy operation does not crash cycle inventory");
  Console.WriteLine("CYCLES_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
